using System;
using System.Linq;
using System.Reflection;
using UnityEngine;
namespace BWVR.Editor {
public static class PlayOutingChecks {
 static readonly BindingFlags Flags=BindingFlags.Instance|BindingFlags.NonPublic;
 static void Require(bool ok,string why){if(!ok)throw new Exception(why);}
 public static void VerifyModel(){
  var old=JsonUtility.FromJson<SliceState>("{}");string before=JsonUtility.ToJson(old);for(int i=0;i<7;i++)PlayOutingText.Read(old,i);Require(old.Valid()&&(old.playOuting==null||old.playOuting.phase==PlayOutingPhase.NotStarted&&old.playOuting.attempts==0)&&JsonUtility.ToJson(old)==before,"Historical read mutated or started outing");
  var w=new WorldPlayMemory();w.Echo.demonstrations=w.Echo.games=1;w.Goals.sharedRounds=1;w.Puzzle.attempts=w.Puzzle.solved=1;var p=new PlayOutingState();Require(p.Begin(w)&&!p.Begin(w)&&p.Observe(w,false)==0,"Old successes or repeated start counted");w.Echo.demonstrations=w.Echo.games=2;Require(p.Observe(w,true)==0&&!p.echo,"Pause credited play");Require(p.Observe(w,false)==1&&p.Observe(w,false)==0,"Echo duplicate / missing outcome");w.Goals.sharedRounds=3;p.Observe(w,false);Require(p.rounds==2&&p.Count==1,"Partial shared rounds completed experiment");
  var state=new SliceState{playOuting=p,worldPlay=w};var saved=JsonUtility.FromJson<SliceState>(JsonUtility.ToJson(state));Require(saved.Valid()&&saved.playOuting.rounds==2&&saved.playOuting.echo,"Pending outing save failed");p=saved.playOuting;w=saved.worldPlay;w.Goals.sharedRounds=4;w.Puzzle.attempts=w.Puzzle.solved=2;Require(p.Observe(w,false)==6&&p.phase==PlayOutingPhase.Complete&&p.completed==1&&p.Observe(w,false)==0&&p.Valid(),"Completion missing or duplicated");Require(PlayOutingText.Read(saved,4).text.Contains("FIELD NOTE"),"Field note not unlocked");Require(p.Begin(w)&&p.Progress==0&&p.unlocked==7&&p.Observe(w,false)==0&&p.End()&&!p.End(),"Replay/end invented or erased progress");Require(PlayOutingText.Read(saved,4).text.Contains("FIELD NOTE"),"Replay hid past notes");p.rounds=4;Require(!p.Valid(),"Invalid progress accepted");p.rounds=0;p.unlocked=8;Require(!p.Valid(),"Invalid unlock mask accepted");
  Debug.Log("BWVR_PLAY_OUTING_MODEL_PASS: pure old-save reading, baseline, partial/paused/exactly-once progress, save/resume, replay, retained notes and corruption guards");
 }
 // Each native activity fixture stages its own world; these are real confirmed counters,
 // not a claim of a natural uninterrupted full-island playthrough.
 public static void VerifyActivities(){
  var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var field=typeof(QuestSlice).GetField("state",Flags);var outing=new PlayOutingState();outing.Begin(null);SliceState observed=null;
  PlayerRhythmChecks.Verify(s=>observed=s);Require(observed!=null&&outing.Observe(observed.worldPlay,false)==1,"Native echoed phrase did not earn outing progress");
  GoalTurnChecks.Verify((ball,gate)=>observed=(SliceState)field.GetValue(slice));Require(outing.Observe(observed.worldPlay,false)==2&&outing.rounds==3,"Native shared turns did not earn outing progress");
  CooperativePuzzleChecks.Verify(ball=>observed=(SliceState)field.GetValue(slice));Require(outing.Observe(observed.worldPlay,false)==4&&outing.phase==PlayOutingPhase.Complete&&outing.completed==1,"Native shared gate did not finish outing");
  Debug.Log("BWVR_PLAY_OUTING_ACTIVITIES_PASS: confirmed native echo, three physical shared goal rounds and cooperative gate passage unlock all three experiments");
 }
 public static void VerifyRuntime(){
  Require(Application.isPlaying,"Enter Play mode");var slice=UnityEngine.Object.FindAnyObjectByType<QuestSlice>();var field=typeof(QuestSlice).GetField("state",Flags);var original=(SliceState)field.GetValue(slice);var test=new SliceState{developmentFocus=true,observeWithoutFoodWork=true};field.SetValue(slice,test);slice.GetComponentInChildren<CreatureHybrid>().Interrupt("Outing QA");slice.SetSanctuaryOpen(false);var root=(GameObject)typeof(QuestSlice).GetField("creationBook",Flags).GetValue(slice);var pointer=typeof(QuestSlice).GetMethod("BookPointer",Flags);var go=(GameObject)typeof(QuestSlice).GetField("outingGo",Flags).GetValue(slice);var held=(CarryItem[])typeof(QuestSlice).GetField("held",Flags).GetValue(slice);
  try{
   Require(slice.ShowCreationBook(true),"Book unavailable");slice.SelectCreationBook(CreationBookSection.Outings);test.paused=true;Require(!slice.BeginPlayOuting(),"Paused outing started");test.paused=false;pointer.Invoke(slice,new object[]{1,true,false,go.GetComponent<Collider>(),false});pointer.Invoke(slice,new object[]{1,true,true,go.GetComponent<Collider>(),true});Require(test.playOuting==null,"Untracked / held input began outing");pointer.Invoke(slice,new object[]{1,true,false,go.GetComponent<Collider>(),true});Require(test.playOuting?.phase==PlayOutingPhase.Active,"Tracked Book action did not begin outing");
   var creature=slice.GetComponentInChildren<CreatureHybrid>().GetComponent<CarryItem>();held[1]=creature;Require(!slice.MarkPlayActivity(0),"Beacon stole a held object");held[1]=null;Require(slice.MarkPlayActivity(0)&&!slice.MenuOpen,"Mark did not return to world");var beacon=(LineRenderer)typeof(QuestSlice).GetField("outingBeacon",Flags).GetValue(slice);Require(beacon.gameObject.activeSelf&&beacon.GetComponent<Collider>()==null,"Beacon missing / physical");float remaining=(float)typeof(QuestSlice).GetField("outingMarkTime",Flags).GetValue(slice);test.paused=true;slice.Simulate(5);Require((float)typeof(QuestSlice).GetField("outingMarkTime",Flags).GetValue(slice)==remaining,"Paused beacon expired");test.paused=false;
   // Publish fixture counters whose native origins are separately checked by the activity suites.
   test.WorldPlay.Echo.demonstrations=test.WorldPlay.Echo.games=1;test.WorldPlay.Goals.sharedRounds=2;slice.Simulate(.01f);Require(test.playOuting.echo&&test.playOuting.rounds==2&&test.playOuting.phase==PlayOutingPhase.Active,"Simulation did not observe confirmed counters");typeof(QuestSlice).GetMethod("Save",Flags).Invoke(slice,null);typeof(QuestSlice).GetMethod("Load",Flags).Invoke(slice,null);test=(SliceState)field.GetValue(slice);Require(test.playOuting.echo&&test.playOuting.rounds==2&&test.Valid(),"Native save/load lost outing");slice.Simulate(.01f);Require(!beacon.gameObject.activeSelf,"Reload retained a stale beacon");test.WorldPlay.Goals.sharedRounds=3;test.WorldPlay.Puzzle.attempts=test.WorldPlay.Puzzle.solved=1;slice.Simulate(.01f);Require(test.playOuting.phase==PlayOutingPhase.Complete&&test.playOuting.completed==1,"Outing did not complete");slice.Simulate(.01f);Require(test.playOuting.completed==1,"Completion replayed");Require(slice.BeginPlayOuting()&&slice.MarkPlayActivity(2)&&slice.EndPlayOuting()&&!beacon.gameObject.activeSelf,"Replay/mark/end cleanup failed");
   Debug.Log("BWVR_PLAY_OUTING_RUNTIME_PASS: Book tracked-edge input, pause/held protection, optional marker, published-counter observation, native save/load, once-only completion, replay and cleanup");
  }finally{held[1]=null;slice.ShowCreationBook(false);slice.SetSanctuaryOpen(false);field.SetValue(slice,original);typeof(QuestSlice).GetMethod("ClearOutingMark",Flags).Invoke(slice,null);}
 }
}
}
